import{_ as d,a0 as i,w as l,s as r,ao as p,I as n,x as o,a1 as t,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"關於 Linux 你可能不是非常瞭解的七件事 | LCTT x X-CMD","titleTemplate":false,"description":"關於 Linux 你可能不是非常瞭解的七件事 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於 Linux 你可能不是非常瞭解的七件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於 Linux 你可能不是非常瞭解的七件事 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170907 Seven things about Linux you may not have known so far","title":"關於 Linux 你可能不是非常瞭解的七件事","tag":"201710","desc":""},"relativePath":"201710/20170907 Seven things about Linux you may not have known so far.md","filePath":"[post].md"}'),c={name:"201710/20170907 Seven things about Linux you may not have known so far.md"};function h(u,e,m,f,x,b){const a=i("Link");return l(),r("div",null,[e[13]||(e[13]=p(`<h1 id="關於-linux-你可能不是非常瞭解的七件事" tabindex="-1">關於 Linux 你可能不是非常瞭解的七件事 <a class="header-anchor" href="#關於-linux-你可能不是非常瞭解的七件事" aria-label="Permalink to “關於 Linux 你可能不是非常瞭解的七件事”">​</a></h1><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2015/12/Linux-Kernel-sys-visual5.jpg?resize=750%2C563" alt="Hidden features of Linux"></p><p>使用 Linux 最酷的事情之一就是隨着時間的推移，你可以不斷獲得新的知識。每天，你都可能會遇到一個新的實用工具，或者只是一個不太熟悉的奇技淫巧，但是卻非常有用。這些零碎的東西並不總是能夠改變生活，但是卻是專業知識的基礎。</p><p>即使是專家，也不可能事事皆知。無論你有多少經驗，可能總會有更多的東西需要你去學習。所以，在這兒我列出了七件關於 Linux 你可能不知道的事情。</p><h3 id="一個查找命令歷史的交互模式" tabindex="-1">一個查找命令歷史的交互模式 <a class="header-anchor" href="#一個查找命令歷史的交互模式" aria-label="Permalink to “一個查找命令歷史的交互模式”">​</a></h3><p>你可能對 <code>history</code> 命令非常熟悉，它會讀取 bash 歷史，然後以編號列表的方式輸出到標準輸出（<code>stdout</code>）。然而，如果你在 <code>curl</code> 命令的海洋裏尋找一個特定的鏈接（URL），那麼這個列表並不總是那麼容易閲讀的。</p><p>你還可以有另一個選擇，Linux 有一個交互式的反向搜索可以幫助你解決這個問題。你可以通過快捷鍵 <code>ctrl+r</code>啓動交互模式，然後進入一個交互提示中，它將會根據你提供的字符串來向後搜索 bash 歷史，你可以通過再次按下 <code>ctrl+r</code> 向後搜索更老的命令，或者按下 <code>ctrl+s</code> 向前搜索。</p><p>注意，<code>ctrl+s</code> 有時會與 XON/XOFF 流控制衝突，即 XON/XOFF 流控制也會使用該快捷鍵。你可以通過運行 <code>stty -ixon</code> 命令來禁用該快捷鍵。在你的個人電腦上，這通常是有用的，但是在禁用前，確保你不需要 XON/XOFF 。</p><h3 id="cron-不是安排任務的唯一方式" tabindex="-1">Cron 不是安排任務的唯一方式 <a class="header-anchor" href="#cron-不是安排任務的唯一方式" aria-label="Permalink to “Cron 不是安排任務的唯一方式”">​</a></h3><p>Cron 任務對於任何水平的系統管理員，無論是毫無經驗的初學者，還是經驗豐富的專家來説，都是非常有用的。但是，如果你需要安排一個一次性的任務，那麼 <code>at</code> 命令為你提供了一個快捷的方式來創建任務，從而你不需要接觸 crontab 。</p><p><code>at</code> 命令的運行方式是在後面緊跟着你想要運行任務的運行時間。時間是靈活的，因為它支持許多時間格式。包括下面這些例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>at 12:00 PM September 30 2017</span></span>
<span class="line"><span>at now + 1 hour</span></span>
<span class="line"><span>at 9:00 AM tomorrow</span></span></code></pre></div><p>當你以帶參數的方式輸入 <code>at</code> 命令以後，將會提示你該命令將在你的 Linux 系統上運行。這可能是一個備份腳本，一套維護任務，或者甚至是一個普通的 bash 命令。如果要結束任務，可以按 <code>ctrl+d</code> 。</p><p>另外，你可以使用 <code>atq</code> 命令查看當前用户的所有任務，或者使用 <code>sudo atq</code> 查看所有用户的任務。它將會展示出所有排定好的任務，並且每個任務都伴有一個 ID 。如果你想取消一個排定好的任務，可以使用 <code>atrm</code> 命令，並且以任務 ID 作為參數。</p><h3 id="你可以按照功能搜索命令-而不僅僅是通過名字" tabindex="-1">你可以按照功能搜索命令，而不僅僅是通過名字 <a class="header-anchor" href="#你可以按照功能搜索命令-而不僅僅是通過名字" aria-label="Permalink to “你可以按照功能搜索命令，而不僅僅是通過名字”">​</a></h3><p>記住命令的名字非常困難，特別是對於初學者來説。幸運的是，Linux 附帶了一個通過名字和描述來搜索 man 頁面的工具。</p><p>下次，如果你沒有記住你想要使用的工具的名稱，你可以嘗試使用 <code>apropos</code> 命令加上你想要乾的事情的描述。比如，<code>apropos build filesystem</code> 將會返回一系列名字和描述包括了 “build” 和 “filesystem” 單詞的工具。</p><p><code>apropos</code> 命令接受一個或多個字符串作為參數，但同時它也有其他參數，比如你可以使用 <code>-r</code> 參數，從而通過正則表達式來搜索。</p><h3 id="一個允許你來管理系統版本的替代系統" tabindex="-1">一個允許你來管理系統版本的替代系統 <a class="header-anchor" href="#一個允許你來管理系統版本的替代系統" aria-label="Permalink to “一個允許你來管理系統版本的替代系統”">​</a></h3><p>如果你曾進行過軟件開發，你就會明白跨項目管理不同版本的語言的支持的重要性。許多 Linux 發行版都有工具可以來處理不同的內建版本。</p><p>可執行文件比如 <code>java</code> 往往符號鏈接到目錄 <code>/etc/alternatives</code> 下。反過來，該目錄會將符號鏈接存儲為二進制文件並提供一個管理這些鏈接的接口。Java 可能是替代系統最常管理的語言，但是，經過一些配置，它也可以作為其他應用程序替代品，比如 NVM 和 RVM （NVM 和 RVM 分別是 NodeJS 和 Ruby 的版本管理器）。</p><p>在基於 Debian 的系統中，你可以使用 <code>update-alternatives</code> 命令創建和管理這些鏈接。在 CentOS 中，這個工具就叫做 <code>alternatives</code> 。通過更改你的 alternatives 文件中的鏈接，你便可以安裝一個語言的多個版本，並且在不同的情況下使用不同的二進制。這個替代系統也提供了對任何你可能在命令列運行的程序的支持。</p><h3 id="shred-命令是更加安全的刪除文件方式" tabindex="-1"><code>shred</code> 命令是更加安全的刪除文件方式 <a class="header-anchor" href="#shred-命令是更加安全的刪除文件方式" aria-label="Permalink to “shred 命令是更加安全的刪除文件方式”">​</a></h3><p>我們大多數時候總是使用 <code>rm</code> 命令來刪除文件。但是文件去哪兒了呢？真相是 <code>rm</code> 命令所做的事情並不是像你所想像的那樣，它僅僅刪除了文件系統和硬盤上的數據的硬鏈接。硬盤上的數據依舊存在，直到被另一個應用重寫覆蓋。對於非常敏感的數據來説，這會帶來一個很大的安全隱患。</p><p><code>shred</code> 命令是 <code>rm</code> 命令的升級版。當你使用 <code>shred</code> 命令刪除一個文件之後，文件中的數據會被多次隨機覆寫。甚至有一個選項可以在隨機覆寫之後對所有的數據進行清零。</p><p>如果你想安全的刪除一個文件並且以零覆蓋，那麼可以使用下面的命令：</p><p><code>shred -u -z [file name]</code></p><p>同時，你也可以使用 <code>-n</code> 選項和一個數字作為參數，從而指定在隨機覆蓋數據的時候迭代多少次。</p><h3 id="通過自動更正來避免輸入很長的無效文件路徑" tabindex="-1">通過自動更正來避免輸入很長的無效文件路徑 <a class="header-anchor" href="#通過自動更正來避免輸入很長的無效文件路徑" aria-label="Permalink to “通過自動更正來避免輸入很長的無效文件路徑”">​</a></h3><p>有多少次，你輸入一個文件的絕對路徑，然而卻看到“沒有該文件或目錄”的消息。任何人都會明白輸入一個很長的字符串的痛苦。幸運的是，有一個很簡單的解決辦法。</p><p>內建的 <code>shopt</code> 命令允許你設置不同的選項來改變 shell 的行為。設置 <code>cdspell</code> 選項是避免輸入文件路徑時一個字母出錯的頭痛的一個簡單方式。你可以通過運行 <code>shopt -s cdspell</code> 命令來啓用該選項。啓用該選項後，當你想要切換目錄時，會自動更正為最匹配的目錄。</p><p>Shell 選項是節省時間的一個好方法（更不用説減少麻煩），此外還有許許多多的其他選項。如果想查看你的系統中所有選項的完整列表，可以運行不帶參數的 <code>shopt</code> 命令。需要注意的是，這是 bash 的特性，如果你運行 zsh 或者其他可供選擇的 shell，可能無法使用。</p><h3 id="通過子-shell-返回到當前目錄" tabindex="-1">通過子 shell 返回到當前目錄 <a class="header-anchor" href="#通過子-shell-返回到當前目錄" aria-label="Permalink to “通過子 shell 返回到當前目錄”">​</a></h3><p>如果你曾經配置過一個比較複雜的系統，那麼你可能會發現你需要頻繁的更換目錄，從而很難跟蹤你所在的位置。如果在運行完一個命令後自動返回到當前位置，不是很好嗎？</p><p>Linux 系統實際上提供了一個解決該問題的方法，並且非常簡單。如果你想通過 <code>cd</code> 命令進入另一個目錄完成一些任務，然後再返回當前工作目錄，那麼你可以將命令置於括號中。你可以在你的 Linux 系統上嘗試下面這個命令。記住你當前的工作目錄，然後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(cd /etc &amp;&amp; ls -a)</span></span></code></pre></div><p>該命令會輸出 <code>/etc</code> 目錄的內容。現在，檢查你的當前工作目錄。它和執行該命令前的目錄一樣，而不是 <code>/etc</code> 目錄。</p><p>它是如何工作的呢？運行一個括號中的命令會創建一個子 shell 或一個當前 shell 進程的復刻副本。該子 shell 可以訪問所有的父變量，反之則不行。所以請記住，你是在運行一個非常複雜的單行命令。</p><p>在並行處理中經常使用子 shell ，但是在命令列中，它也能為你帶來同樣的力量，從而使你在瀏覽文件系統時更加容易。</p><hr><p>作者簡介：</p><p>Phil Zona 是 Linux Academy 的技術作家。他編寫了 AWS、Microsoft Azure 和 Linux 系統管理的指南和教程。他同時也管理着 Cloud Assessments Blog，該Blog旨在幫助個人通過技術實現他們的事業目標。</p><hr>`,43)),n("p",null,[e[1]||(e[1]=o("via: ",-1)),t(a,{href:"http://opensourceforu.com/2017/09/top-7-things-linux-may-not-known-far/"},{default:s(()=>[...e[0]||(e[0]=[o("http://opensourceforu.com/2017/09/top-7-things-linux-may-not-known-far/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=o("作者：",-1)),t(a,{href:"http://opensourceforu.com/author/phil-zona/"},{default:s(()=>[...e[2]||(e[2]=[o("PHIL ZONA",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),t(a,{href:"https://github.com/ucasFL"},{default:s(()=>[...e[3]||(e[3]=[o("ucasFL",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const C=d(c,[["render",h]]);export{k as __pageData,C as default};
